CREATE FUNCTION public.convert_partnership(request_uuid uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.partnership_requests; salon_key text; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO q FROM public.partnership_requests WHERE id=request_uuid FOR UPDATE; IF NOT FOUND OR q.status<>'accepted' THEN RAISE EXCEPTION 'Accepted request required'; END IF; IF q.salon_id IS NOT NULL THEN RETURN q.salon_id; END IF; salon_key:='request-'||q.id::text; INSERT INTO public.salons(id,slug,name,city,area,is_demo,data) VALUES(salon_key,salon_key,q.business,q.city,q.area,q.is_demo,jsonb_build_object('id',salon_key,'slug',salon_key,'name',q.business,'city',q.city,'area',q.area,'published',false,'archived',false,'isDemo',q.is_demo,'status','unverified','address','','distanceKm',0,'categories',to_jsonb(q.categories),'image','interior','about',q.message,'phone',CASE WHEN q.is_demo THEN '' ELSE q.phone END,'website',q.website,'instagram',q.instagram,'openHour',10,'closeHour',20,'closedDay',5,'hours','','attributes','[]'::jsonb,'map',jsonb_build_object('x',50,'y',50),'services','[]'::jsonb,'staff','[]'::jsonb,'portfolio','[]'::jsonb,'credentials','[]'::jsonb,'addedAt',current_date::text,'checkedAt',current_date::text)); UPDATE public.partnership_requests SET salon_id=salon_key WHERE id=q.id; RETURN salon_key; END $$;
REVOKE ALL ON FUNCTION public.convert_partnership(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.convert_partnership(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.notify_review_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.user_id AND notifications) THEN RETURN NEW; END IF; IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('approved','rejected','hidden') THEN INSERT INTO public.user_notifications(user_id,event,record_id,message) VALUES(NEW.user_id,'review-'||NEW.status,NEW.id::text,CASE NEW.status WHEN 'approved' THEN 'نظر شما منتشر شد.' WHEN 'rejected' THEN 'نظر شما منتشر نشد؛ بازخورد بررسی را در نظرهای من ببینید.' ELSE 'نظر شما از نمایش عمومی خارج شد.' END); END IF; IF NEW.reply IS DISTINCT FROM OLD.reply AND COALESCE(NEW.reply,'')<>'' THEN INSERT INTO public.user_notifications(user_id,event,record_id,message) VALUES(NEW.user_id,'review-reply',NEW.id::text,'پاسخ رسمی به نظر شما ثبت شد.'); END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.notify_report_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.resolved AND NOT OLD.resolved AND EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.user_id AND notifications) THEN INSERT INTO public.user_notifications(user_id,event,record_id,message) VALUES(NEW.user_id,'report-resolved',NEW.review_id::text,'رسیدگی به گزارش نظر شما پایان یافت.'); END IF; RETURN NEW; END $$;
CREATE TRIGGER audit_categories AFTER INSERT OR UPDATE ON public.directory_categories FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TRIGGER audit_locations AFTER INSERT OR UPDATE ON public.directory_locations FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();